// One item per Google Maps results page: every active row of the Searches tab x the pages to fetch
const s = $('Settings').first().json;
const pages = Math.min(Math.max(parseInt(s.pages_per_search, 10) || 1, 1), 5);
const out = [];
for (const { json: r } of $input.all()) {
  const query = String(r.query || '').trim();
  const city = String(r.city || '').trim();
  if (!query || !city) continue;
  if (/^(no|false|0|paused)$/i.test(String(r.active ?? '').trim())) continue;
  for (let page = 1; page <= pages; page++) {
    out.push({ json: { search: `${query} in ${city}`, query, city, page } });
  }
}
if (!out.length) throw new Error('No active searches. Add rows with a query and a city to the Searches tab.');
return out;

// Remembers which search each place came from (the loop handles one search page at a time)
const ctx = $('Loop over searches').first().json;
return $input.all().map((item) => ({ json: { ...item.json, _search: ctx.search, _city: ctx.city } }));

// A failed page becomes one marked item, so the loop carries on and the error is logged at the end
const ctx = $('Loop over searches').first().json;
const err = $input.first().json.error || 'unknown error';
return [{ json: { _failed: true, step: 'google-maps search', search: ctx.search, page: ctx.page, error: String(err).slice(0, 300), at: new Date().toISOString() } }];

// Keeps open places that meet the rating and review bar, one item per unique place
const s = $('Settings').first().json;
const minRating = Number(s.min_rating) || 0;
const minReviews = Number(s.min_reviews) || 0;
const seen = new Set();
const out = [];
for (const { json: p } of $input.all()) {
  if (!p.place_id || seen.has(p.place_id)) continue; // empty result pages carry no place_id
  seen.add(p.place_id);
  if (p.permanently_closed) continue;
  if (p.business_status && p.business_status !== 'OPEN') continue;
  const rating = Number(p.stars ?? p.rating) || 0;
  const reviews = Number(p.review_count) || 0;
  if (rating < minRating || reviews < minReviews) continue;
  out.push({ json: {
    place_id: p.place_id,
    name: p.name || '',
    category: p.category || p.type || '',
    city: p.city || p._city || '',
    state: p.state || '',
    address: p.full_address || p.address || '',
    phone: p.phone_international || p.phone || '',
    website: p.website || '',
    domain: String(p.website_domain || '').toLowerCase().replace(/^www\./, ''),
    rating,
    reviews,
    verified: p.verified === true,
    has_booking: Boolean(p.booking_link || p.reservations_link || p.order_link),
    maps_url: p.url || p.place_link || '',
    search: p._search || '',
  } });
}
return out;

// Dedupe against the Leads tab (by place_id and, optionally, by website domain) and within this run
const s = $('Settings').first().json;
const skipDomains = s.skip_known_domains !== false;
const max = parseInt(s.max_new_leads_per_run, 10) || 50;
const knownIds = new Set();
const knownDomains = new Set();
for (const { json: row } of $input.all()) {
  if (row.place_id) knownIds.add(String(row.place_id));
  if (row.domain) knownDomains.add(String(row.domain).toLowerCase());
}
const byDomain = new Map();
const out = [];
for (const { json: lead } of $('Clean and pre-qualify').all()) {
  if (knownIds.has(lead.place_id)) continue;
  if (lead.domain && skipDomains && knownDomains.has(lead.domain)) continue;
  // several branches of one business share a website: keep the best-reviewed one, count the rest
  if (lead.domain && byDomain.has(lead.domain)) {
    const first = byDomain.get(lead.domain);
    first.other_locations += 1;
    if (lead.reviews > first.reviews) Object.assign(first, { ...lead, other_locations: first.other_locations });
    continue;
  }
  const entry = { ...lead, other_locations: 0 };
  if (lead.domain) byDomain.set(lead.domain, entry);
  out.push(entry);
}
out.sort((a, b) => b.reviews - a.reviews);
return out.slice(0, max).map((json) => ({ json }));

// Adds the emails, phones and social profiles found on the lead's website
const lead = $('Loop over leads').first().json;
const c = $input.first().json;
if (c.error) {
  return [{ json: { ...lead, best_email: '', best_email_type: '', email_on_own_domain: false, emails: '', contact_phones: '', socials: '', social_count: 0, enrichment: `lookup failed: ${String(c.error).slice(0, 150)}` } }];
}
const generic = /^(info|hello|contact|office|admin|support|sales|team|reception|frontdesk|appointments?|booking|bookings|mail|enquiries|inquiries)@/;
const emails = (c.emails || [])
  .map((e) => ({ email: String(e.email || '').toLowerCase(), own: e.own_domain === true }))
  .filter((e) => e.email)
  // own-domain addresses first, then named people before generic inboxes
  .sort((a, b) => (Number(b.own) - Number(a.own)) || (Number(generic.test(a.email)) - Number(generic.test(b.email))));
const best = emails[0];
const socials = Object.entries(c.socials || {})
  .filter(([, urls]) => Array.isArray(urls) && urls.length)
  .map(([network, urls]) => `${network}: ${urls[0]}`);
return [{ json: {
  ...lead,
  best_email: best ? best.email : '',
  best_email_type: !best ? '' : generic.test(best.email) ? 'generic' : 'personal',
  email_on_own_domain: best ? best.own : false,
  emails: emails.map((e) => e.email).join(', '),
  contact_phones: (c.phones || []).map((p) => p.e164 || p.phone).filter(Boolean).join(', '),
  socials: socials.join(' | '),
  social_count: socials.length,
  enrichment: 'ok',
} }];

// Scores each lead 0-100 from reputation, reachability and online presence, and says why
const s = $('Settings').first().json;
const hot = Number(s.hot_score) || 70;
const warm = Number(s.warm_score) || 45;
const now = new Date().toISOString();
return $input.all().map(({ json: l }) => {
  let score = 0;
  const why = [];
  if (l.rating >= 4.7) { score += 20; why.push(`rating ${l.rating}`); }
  else if (l.rating >= 4.3) { score += 12; why.push(`rating ${l.rating}`); }
  else if (l.rating >= 4.0) score += 6;
  const reviews = Number(l.reviews) || 0;
  score += Math.min(20, Math.round(Math.log10(reviews + 1) * 8)); // diminishing returns on review volume
  if (reviews >= 100) why.push('well reviewed');
  if (l.website) score += 10; else why.push('no website');
  if (l.best_email) { score += l.best_email_type === 'personal' ? 25 : 18; why.push(`${l.best_email_type} email`); }
  if (l.email_on_own_domain) score += 5;
  if (l.phone) score += 5;
  score += Math.min(10, (Number(l.social_count) || 0) * 4);
  if (l.verified) score += 3;
  if (l.has_booking) { score += 2; why.push('takes online bookings'); }
  if (l.other_locations > 0) why.push(`multi-location (+${l.other_locations})`);
  score = Math.min(100, score);
  return { json: {
    place_id: l.place_id, name: l.name, category: l.category, city: l.city, state: l.state, address: l.address,
    phone: l.phone, website: l.website, domain: l.domain, best_email: l.best_email || '', best_email_type: l.best_email_type || '',
    emails: l.emails || '', contact_phones: l.contact_phones || '', socials: l.socials || '',
    rating: l.rating, reviews: l.reviews, other_locations: l.other_locations || 0,
    score, tier: score >= hot ? 'hot' : score >= warm ? 'warm' : 'cold', score_reasons: why.join('; '),
    maps_url: l.maps_url, search: l.search, enrichment: l.enrichment || 'no website', status: 'new', found_at: now,
  } };
});

// Summary email: totals per tier and per search, and the top leads of this run
const rows = $input.all().map((i) => i.json);
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const tiers = { hot: 0, warm: 0, cold: 0 };
const bySearch = {};
for (const r of rows) {
  tiers[r.tier] = (tiers[r.tier] || 0) + 1;
  bySearch[r.search] = (bySearch[r.search] || 0) + 1;
}
const failed = $('Failed search?').all(0).length;
const top = [...rows].sort((a, b) => b.score - a.score).slice(0, 20);
const table = top.map((r) => `<tr><td>${r.score}</td><td>${esc(r.tier)}</td><td><a href="${esc(r.maps_url)}">${esc(r.name)}</a></td><td>${esc(r.category)}</td><td>${esc(r.city)}</td><td>${esc(r.best_email)}</td><td>${esc(r.phone)}</td></tr>`).join('');
const searches = Object.entries(bySearch).map(([q, n]) => `<li>${esc(q)}: ${n}</li>`).join('');
const html = `<h2>New local leads</h2>
<p><b>${rows.length}</b> new leads saved to your sheet: <b>${tiers.hot}</b> hot, <b>${tiers.warm}</b> warm, <b>${tiers.cold}</b> cold.${failed ? ` ${failed} search page(s) failed (see the Errors tab).` : ''}</p>
<h3>By search</h3><ul>${searches}</ul>
<h3>Top leads</h3>
<table border="1" cellpadding="4" cellspacing="0"><tr><th>Score</th><th>Tier</th><th>Business</th><th>Category</th><th>City</th><th>Email</th><th>Phone</th></tr>${table}</table>`;
return [{ json: { subject: `Lead digest: ${rows.length} new (${tiers.hot} hot)`, html } }];

// One Slack message with the hot leads, best first
const leads = $input.all().map((i) => i.json).sort((a, b) => b.score - a.score);
const lines = leads.slice(0, 15).map((l) =>
  `• *${l.name}* (${l.category}, ${l.city}) score ${l.score}
   ${l.best_email || 'no email'} · ${l.phone || 'no phone'} · <${l.maps_url}|Maps>${l.website ? ` · <${l.website}|site>` : ''}
   _${l.score_reasons}_`);
const more = leads.length > 15 ? `
…and ${leads.length - 15} more in the Leads tab.` : '';
return [{ json: { text: `:fire: *${leads.length} hot lead${leads.length === 1 ? '' : 's'} ready for outreach*

${lines.join('
')}${more}` } }];
